-- Rwanda CHW Reporting System
-- Complete database installation: schema + seed data
-- Safe to import into phpMyAdmin as a single SQL file.

CREATE DATABASE IF NOT EXISTS `rwanda_chw_reporting`
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE `rwanda_chw_reporting`;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `user_preferences`;
DROP TABLE IF EXISTS `audit_logs`;
DROP TABLE IF EXISTS `notifications`;
DROP TABLE IF EXISTS `reports`;
DROP TABLE IF EXISTS `community_events`;
DROP TABLE IF EXISTS `education_sessions`;
DROP TABLE IF EXISTS `referrals`;
DROP TABLE IF EXISTS `visits`;
DROP TABLE IF EXISTS `households`;
DROP TABLE IF EXISTS `chws`;
DROP TABLE IF EXISTS `facilities`;
DROP TABLE IF EXISTS `users`;
DROP TABLE IF EXISTS `villages`;
DROP TABLE IF EXISTS `cells`;
DROP TABLE IF EXISTS `sectors`;
DROP TABLE IF EXISTS `districts`;
DROP TABLE IF EXISTS `provinces`;

CREATE TABLE provinces (id VARCHAR(20) PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE districts (id VARCHAR(20) PRIMARY KEY,province_id VARCHAR(20) NOT NULL,name VARCHAR(120) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(province_id) REFERENCES provinces(id),INDEX(province_id)) ENGINE=InnoDB;
CREATE TABLE sectors (id VARCHAR(30) PRIMARY KEY,district_id VARCHAR(20) NOT NULL,name VARCHAR(120) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(district_id) REFERENCES districts(id),INDEX(district_id)) ENGINE=InnoDB;
CREATE TABLE cells (id VARCHAR(40) PRIMARY KEY,sector_id VARCHAR(30) NOT NULL,name VARCHAR(120) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(sector_id) REFERENCES sectors(id),INDEX(sector_id)) ENGINE=InnoDB;
CREATE TABLE villages (id VARCHAR(50) PRIMARY KEY,cell_id VARCHAR(40) NOT NULL,name VARCHAR(120) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(cell_id) REFERENCES cells(id),INDEX(cell_id)) ENGINE=InnoDB;
CREATE TABLE facilities (id VARCHAR(30) PRIMARY KEY,name VARCHAR(180) NOT NULL,type VARCHAR(80) NOT NULL,district_id VARCHAR(20),sector_id VARCHAR(30),status VARCHAR(30) NOT NULL DEFAULT 'active',phone VARCHAR(40),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(district_id) REFERENCES districts(id),FOREIGN KEY(sector_id) REFERENCES sectors(id),INDEX(district_id),INDEX(sector_id)) ENGINE=InnoDB;
CREATE TABLE users (id VARCHAR(30) PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,role VARCHAR(50) NOT NULL,province_id VARCHAR(20),district_id VARCHAR(20),sector_id VARCHAR(30),facility_id VARCHAR(30),status VARCHAR(30) NOT NULL DEFAULT 'active',password_hash VARCHAR(255) NOT NULL,last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(province_id) REFERENCES provinces(id),FOREIGN KEY(district_id) REFERENCES districts(id),FOREIGN KEY(sector_id) REFERENCES sectors(id),FOREIGN KEY(facility_id) REFERENCES facilities(id),INDEX(role),INDEX(district_id)) ENGINE=InnoDB;
CREATE TABLE chws (id VARCHAR(30) PRIMARY KEY,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,gender VARCHAR(30),date_of_birth DATE,phone VARCHAR(40),email VARCHAR(190),nationality VARCHAR(80),province_id VARCHAR(20),district_id VARCHAR(20),sector_id VARCHAR(30),cell_id VARCHAR(40),village_id VARCHAR(50),facility_id VARCHAR(30),supervisor_id VARCHAR(30),date_joined DATE,status VARCHAR(30) DEFAULT 'active',training_status VARCHAR(80),last_reporting_date DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(province_id) REFERENCES provinces(id),FOREIGN KEY(district_id) REFERENCES districts(id),FOREIGN KEY(sector_id) REFERENCES sectors(id),FOREIGN KEY(cell_id) REFERENCES cells(id),FOREIGN KEY(village_id) REFERENCES villages(id),FOREIGN KEY(facility_id) REFERENCES facilities(id),FOREIGN KEY(supervisor_id) REFERENCES users(id),INDEX(district_id),INDEX(sector_id),INDEX(facility_id)) ENGINE=InnoDB;
CREATE TABLE households (id VARCHAR(30) PRIMARY KEY,village_id VARCHAR(50),cell_id VARCHAR(40),sector_id VARCHAR(30),district_id VARCHAR(20),province_id VARCHAR(20),head_reference VARCHAR(80) NOT NULL,household_size INT NOT NULL DEFAULT 1,vulnerability VARCHAR(60),chw_id VARCHAR(30),registration_date DATE,last_visit DATE,follow_up_required BOOLEAN DEFAULT FALSE,status VARCHAR(30) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(village_id) REFERENCES villages(id),FOREIGN KEY(cell_id) REFERENCES cells(id),FOREIGN KEY(sector_id) REFERENCES sectors(id),FOREIGN KEY(district_id) REFERENCES districts(id),FOREIGN KEY(province_id) REFERENCES provinces(id),FOREIGN KEY(chw_id) REFERENCES chws(id),INDEX(chw_id),INDEX(district_id)) ENGINE=InnoDB;
CREATE TABLE visits (id VARCHAR(30) PRIMARY KEY,chw_id VARCHAR(30) NOT NULL,household_id VARCHAR(30),visit_date DATE NOT NULL,visit_type VARCHAR(80),reason VARCHAR(255),observations TEXT,health_education_provided BOOLEAN DEFAULT FALSE,referral_required BOOLEAN DEFAULT FALSE,follow_up_required BOOLEAN DEFAULT FALSE,follow_up_date DATE,notes TEXT,status VARCHAR(40) DEFAULT 'completed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(chw_id) REFERENCES chws(id),FOREIGN KEY(household_id) REFERENCES households(id),INDEX(chw_id),INDEX(visit_date)) ENGINE=InnoDB;
CREATE TABLE referrals (id VARCHAR(30) PRIMARY KEY,chw_id VARCHAR(30) NOT NULL,referral_date DATE NOT NULL,household_id VARCHAR(30),client_reference VARCHAR(80),reason_category VARCHAR(100),facility_id VARCHAR(30),urgency VARCHAR(40),status VARCHAR(60),facility_response TEXT,outcome TEXT,follow_up_required BOOLEAN DEFAULT FALSE,follow_up_date DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(chw_id) REFERENCES chws(id),FOREIGN KEY(household_id) REFERENCES households(id),FOREIGN KEY(facility_id) REFERENCES facilities(id),INDEX(chw_id),INDEX(status),INDEX(facility_id)) ENGINE=InnoDB;
CREATE TABLE education_sessions (id VARCHAR(30) PRIMARY KEY,session_date DATE NOT NULL,location VARCHAR(180),topic VARCHAR(180),participants INT DEFAULT 0,female_participants INT DEFAULT 0,male_participants INT DEFAULT 0,youth_participants INT DEFAULT 0,target_group VARCHAR(120),duration_minutes INT DEFAULT 0,chw_id VARCHAR(30),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(chw_id) REFERENCES chws(id),INDEX(chw_id),INDEX(session_date)) ENGINE=InnoDB;
CREATE TABLE community_events (id VARCHAR(30) PRIMARY KEY,event_date DATE NOT NULL,location VARCHAR(180),event_type VARCHAR(120),participants INT DEFAULT 0,organizing_chw_id VARCHAR(30),description TEXT,follow_up_required BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(organizing_chw_id) REFERENCES chws(id),INDEX(organizing_chw_id),INDEX(event_date)) ENGINE=InnoDB;
CREATE TABLE reports (id VARCHAR(30) PRIMARY KEY,chw_id VARCHAR(30) NOT NULL,period CHAR(7) NOT NULL,submitted_at DATETIME NULL,status VARCHAR(40) NOT NULL DEFAULT 'DRAFT',households_visited INT DEFAULT 0,household_followups INT DEFAULT 0,health_education_sessions INT DEFAULT 0,referrals INT DEFAULT 0,referral_followups INT DEFAULT 0,maternal_activities INT DEFAULT 0,child_activities INT DEFAULT 0,community_events INT DEFAULT 0,other_activities INT DEFAULT 0,supervisor_comment TEXT,reviewed_by VARCHAR(30),reviewed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_chw_period(chw_id,period),FOREIGN KEY(chw_id) REFERENCES chws(id),FOREIGN KEY(reviewed_by) REFERENCES users(id),INDEX(status),INDEX(period)) ENGINE=InnoDB;
CREATE TABLE notifications (id VARCHAR(40) PRIMARY KEY,user_id VARCHAR(30),title VARCHAR(180) NOT NULL,message TEXT NOT NULL,read_flag BOOLEAN DEFAULT FALSE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(user_id,read_flag)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id VARCHAR(50) PRIMARY KEY,user_id VARCHAR(30),action VARCHAR(80) NOT NULL,resource VARCHAR(80),resource_id VARCHAR(80),description TEXT,ip_address VARCHAR(45),user_agent VARCHAR(500),timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(user_id),INDEX(timestamp),INDEX(resource)) ENGINE=InnoDB;

CREATE TABLE user_preferences (user_id VARCHAR(30) PRIMARY KEY,reduce_motion BOOLEAN NOT NULL DEFAULT FALSE,high_contrast BOOLEAN NOT NULL DEFAULT FALSE,language VARCHAR(10) NOT NULL DEFAULT 'en',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;

